  $email=get_userdata($subscriber)->user_email;pk_upsert_factor($subscriber,'email','verified',pk_hmac($email),[],$email);update_user_meta($subscriber,'dsa_notification_preferences',['topics'=>['newsletter'],'channels'=>['email'],'topicChannels'=>[],'browserPermission'=>'denied']);
  $preview=$read('mcp.campaign.read',['area'=>'audience','id'=>$draft['id']]);$check($preview['data']['count']===1&&!str_contains(wp_json_encode($preview),$email)&&!str_contains(wp_json_encode($preview),'kiwe_unsubscribe='),'Verified native opt-in yields aggregate reach without identities or unsubscribe secrets');
  $pending=$prepare('mcp.campaign.queue',['id'=>$draft['id']]);$intents->approve($pending['id'],$auth,true);update_user_meta($subscriber,'dsa_notification_preferences',['topics'=>[],'channels'=>[]]);$denied(fn()=>$intents->apply($pending['id']),'Stale native campaign audience refused');$check(!get_option('dsa_notification_campaign_active',null),'Revoked native consent invalidates an exact pending send approval');
